from pathlib import Path
root=Path(__file__).parent
fragment=(root/'src/instrument.html').read_text()
# Always build with the same numerical model exercised by the automated checks.
a=fragment.index('const norm =');b=fragment.index("const root=document.getElementById",a)
fragment=fragment[:a]+(root/'src/flight-math.mjs').read_text().replace('export ','')+'\n'+fragment[b:]
css='''
:root{color-scheme:light dark;--background:light-dark(#f8f7f3,#1b2026);--foreground:light-dark(#202b37,#e7e9ec);--muted:light-dark(#e8e9e4,#283039);--border:light-dark(#a4acae,#697783);--viz-series-1:light-dark(#8e342d,#f5ad92);font:15px/1.5 system-ui,sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--background);color:var(--foreground)}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:28px;margin:0}button,input,select{font:inherit;color:inherit}button,select,summary{cursor:pointer}.btn{border:1px solid var(--border);background:var(--background);padding:9px 13px;border-radius:6px;min-height:42px}.btn:hover{background:var(--muted)}.btn[aria-pressed=true],.btn-primary{background:var(--foreground);color:var(--background)}.btn-primary:hover,.btn[aria-pressed=true]:hover{background:var(--foreground);color:var(--background)}.btn:disabled{opacity:.45;cursor:default}.form-label{display:grid;gap:4px;font-size:13px}.form-control,.form-select{min-height:42px;padding:8px;width:100%;min-width:0;border:1px solid var(--border);border-radius:5px;background:var(--background)}.viz-row{display:flex;flex-wrap:wrap;gap:7px}.text-small{font-size:13px}.tabular-nums,output{font-variant-numeric:tabular-nums}output{display:block}details{border-top:1px solid var(--border);padding:14px 0}summary{font-weight:600;margin-bottom:12px}p{max-width:75ch;margin:8px 0}.controls{margin-bottom:10px}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--viz-series-1);outline-offset:3px}::selection{background:var(--foreground);color:var(--background)}.instrument{max-height:950px}.viewport{max-width:850px;width:100%;margin:auto}footer{margin:25px 0;font-size:13px}a{color:inherit;text-underline-offset:3px}@media(max-width:600px){main{padding:12px}.btn{min-height:44px}.controls label{flex-basis:140px}.instrument{max-height:none}}@media print{button,.controls,details,#hint,#readout,footer{display:none!important}main{padding:0}.instrument{max-height:none}}
'''
boot='''<script>
(()=>{let state=null;try{state=JSON.parse(localStorage.getItem('crap-5-state-v2'))}catch{}window.openai={widgetState:state,setWidgetState:async value=>{window.openai.widgetState=value;try{localStorage.setItem('crap-5-state-v2',JSON.stringify(value))}catch{}}};})();
</script>'''
html='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Crap-5 interactive flight computer: slide rule, airspeed and altitude windows, Mach, fuel conversions and wind navigation."><title>Crap-5 · Interactive flight computer</title><style>'+css+'</style></head><body><main>'+boot+fragment+'<footer>Independent simulator. Scale layout is redrawn; compressibility uses an exact subsonic model rather than the printed approximation. True altitude uses the handbook’s instructional approximation. For training, not operational navigation. <a href="https://www.pooleys.com/media/7870/crp-5-booklet-2017.pdf">CRP-5 manual</a> · <a href="https://github.com/captaincomplex/crap-5">Source</a></footer></main></body></html>'
(root/'index.html').write_text(html)
print(root/'index.html')
